44	static void lcd_cfg_panel_info(struct panel_extend_para *info)
45	{
46		u32 i = 0, j = 0;
47		u32 items;
48		u8 lcd_gamma_tbl[][2] = {
49			{0, 0},
50			{15, 15},
51			{30, 30},
52			{45, 45},
53			{60, 60},
54			{75, 75},
55			{90, 90},
56			{105, 105},
57			{120, 120},
58			{135, 135},
59			{150, 150},
60			{165, 165},
61			{180, 180},
62			{195, 195},
63			{210, 210},
64			{225, 225},
65			{240, 240},
66			{255, 255},
67		};
68	
69		u32 lcd_cmap_tbl[2][3][4] = {
70		{
71			{LCD_CMAP_G0, LCD_CMAP_B1, LCD_CMAP_G2, LCD_CMAP_B3},
72			{LCD_CMAP_B0, LCD_CMAP_R1, LCD_CMAP_B2, LCD_CMAP_R3},
73			{LCD_CMAP_R0, LCD_CMAP_G1, LCD_CMAP_R2, LCD_CMAP_G3},
74			},
75			{
76			{LCD_CMAP_B3, LCD_CMAP_G2, LCD_CMAP_B1, LCD_CMAP_G0},
77			{LCD_CMAP_R3, LCD_CMAP_B2, LCD_CMAP_R1, LCD_CMAP_B0},
78			{LCD_CMAP_G3, LCD_CMAP_R2, LCD_CMAP_G1, LCD_CMAP_R0},
79			},
80		};
81	
82		items = sizeof(lcd_gamma_tbl) / 2;
83		for (i = 0; i < items - 1; i++) {
84			u32 num = lcd_gamma_tbl[i+1][0] - lcd_gamma_tbl[i][0];
85	
86			for (j = 0; j < num; j++) {
87				u32 value = 0;
88	
89				value = lcd_gamma_tbl[i][1] +
90					((lcd_gamma_tbl[i+1][1] - lcd_gamma_tbl[i][1])
91					* j) / num;
92				info->lcd_gamma_tbl[lcd_gamma_tbl[i][0] + j] =
93								(value<<16)
94								+ (value<<8) + value;
95			}
96		}
97		info->lcd_gamma_tbl[255] = (lcd_gamma_tbl[items-1][1]<<16) +
98						(lcd_gamma_tbl[items-1][1]<<8)
99						+ lcd_gamma_tbl[items-1][1];
100	
101		memcpy(info->lcd_cmap_tbl, lcd_cmap_tbl, sizeof(lcd_cmap_tbl));
102	
103	}
