116	static s32 lcd_open_flow(u32 sel)
117	{
118	    syslog(LOG_INFO, "BOE_1200x1920: Starting LCD open flow, sel=%lu\n", sel);
119	
120	    LCD_OPEN_FUNC(sel, lcd_power_on, 10);
