129	static s32 lcd_close_flow(u32 sel)
130	{
131	    syslog(LOG_INFO, "BOE_1200x1920: Starting LCD close flow, sel=%lu\n", sel);
132	
133	    LCD_CLOSE_FUNC(sel, lcd_bl_close, 0);
134	    LCD_CLOSE_FUNC(sel, sunxi_lcd_tcon_disable, 0);
135	    LCD_CLOSE_FUNC(sel, lcd_panel_exit, 200);
136	    LCD_CLOSE_FUNC(sel, lcd_power_off, 500);
137	
138	    return 0;
139	}
