141	/* 上电时序 */
142	static void lcd_power_on(u32 sel)
143	{
144	    panel_reset(sel, GPIO_DATA_LOW);
145	    sunxi_lcd_power_enable(sel, AXP2101_ID_DCDC1);
146	    sunxi_lcd_power_enable(sel, AXP2101_ID_DCDC3);
147	    sunxi_lcd_delay_ms(20);
148	    sunxi_lcd_pin_cfg(sel, 1);
149	    sunxi_lcd_delay_ms(50);
150	    panel_reset(sel, GPIO_DATA_HIGH);
151	    sunxi_lcd_delay_ms(20);
152	    panel_reset(sel, GPIO_DATA_LOW);
153	    sunxi_lcd_delay_ms(30);
154	    panel_reset(sel, GPIO_DATA_HIGH);
155	    sunxi_lcd_delay_ms(30);
156	    sunxi_lcd_power_enable(sel, AXP2101_ID_DCDC2);
157	    sunxi_lcd_delay_ms(20);
158	    sunxi_lcd_dsi_clk_enable(sel);
159	    syslog(LOG_INFO, "BOE_1200x1920: Power-on sequence completed\n");
160	}
161	
162	/* 下电时序 (上电的逆序) */
163	static void lcd_power_off(u32 sel)
164	{
165	    syslog(LOG_INFO, "BOE_1200x1920: Power off sequence started\n");
166	    sunxi_lcd_dsi_clk_disable(sel);
167	    sunxi_lcd_delay_ms(20);
168	    sunxi_lcd_power_disable(sel, AXP2101_ID_DCDC2);
169	    sunxi_lcd_delay_ms(20);
170	    panel_reset(sel, GPIO_DATA_LOW);
171	    sunxi_lcd_delay_ms(20);
172	    sunxi_lcd_pin_cfg(sel, 0);
173	    sunxi_lcd_delay_ms(20);
174	    sunxi_lcd_power_disable(sel, AXP2101_ID_DCDC3);
175	    sunxi_lcd_power_disable(sel, AXP2101_ID_DCDC1);
176	}
