178	/* 开启背光 */
179	static void lcd_bl_open(u32 sel)
180	{
181	    syslog(LOG_INFO, "BOE_1200x1920: Enabling PWM backlight\n");
182	    sunxi_lcd_pwm_enable(sel);
183	    sunxi_lcd_delay_ms(100);
184	    sunxi_lcd_backlight_enable(sel);
185	    sunxi_lcd_delay_ms(100);
186	}
187	
188	/* 关闭背光 */
189	static void lcd_bl_close(u32 sel)
190	{
191	    syslog(LOG_INFO, "BOE_1200x1920: Backlight off\n");
192	    sunxi_lcd_backlight_disable(sel);
193	    sunxi_lcd_pwm_disable(sel);
194	    sunxi_lcd_delay_ms(200);
195	}
