27	// 获取EK79007AD2芯片级配置的函数
28	static u32 get_ek79007ad2_config(u32 sel, struct ek79007ad2_config *config)
29	{
30	    struct disp_panel_para panel_info;
31	    config->address_mode = 0x01;    // SHLR=1右移模式
32	    config->power_enable = 0x01;    // PWR_EN=1
33	    config->frame_inversion = 0x00; // FRAME=0默认帧反转
34	
35	    config->gamma_values[0] = 0xAC; // R80h
36	    config->gamma_values[1] = 0xB8; // R81h
37	    config->gamma_values[2] = 0x09; // R82h
38	    config->gamma_values[3] = 0x78; // R83h
39	    config->gamma_values[4] = 0x7F; // R84h
40	    config->gamma_values[5] = 0xBB; // R85h
41	    config->gamma_values[6] = 0x70; // R86h
42	
43	    if (bsp_disp_get_panel_info(sel, &panel_info) != 0) {
44	        syslog(LOG_INFO, "fisker get panel_info fail\n");
45	        return 1;
46	    }
47	    // 根据配置文件中的分辨率设置RES位
48	    if (panel_info.lcd_x == 1024 && panel_info.lcd_y == 600) {
49	        config->res_config = 0x30; // RES[2:1]=00 :1024x600,RES[5] = 1 : H-FRC enable,RES[4] = 1 :Enable internal dithering function
50	    }
51	    else{
52	        syslog(LOG_INFO, "fisker lcd_x and lcd_y set wrong\n");
53	        return 1;
54	    }
55	    if(panel_info.lcd_dsi_lane == 4){
56	        config->lane_config = 0x30;        // RB2h: En_3lane=1, En_2lane=1 (4-lane), NBW=0 (normally white)
57	        syslog(LOG_INFO, "fisker T070S140B: Setting 4-lane MIPI (En_3lane=1, En_2lane=1)\n");
58	    }
59	    else{
60	        syslog(LOG_INFO, "fisker lane number set wrong\n");
61	        return 1;
62	    }
63	return 0;
64	}
