66	static void lcd_cfg_panel_info(struct panel_extend_para *info){
67	
68	    syslog(LOG_INFO, "fisker T070S140B: Configuring panel info...\n");
69	
70	    if (!info) {
71	        syslog(LOG_ERR, "fisker T070S140B: ERROR - panel info pointer is NULL!\n");
72	        return;
73	    }
74	
75	    u32 i = 0, j = 0;
76	    u32 items;
77	
78	    u8 lcd_gamma_tbl[][2] = {
79			{0, 0},
80			{15, 15},
81			{30, 30},
82			{45, 45},
83			{60, 60},
84			{75, 75},
85			{90, 90},
86			{105, 105},
87			{120, 120},
88			{135, 135},
89			{150, 150},
90			{165, 165},
91			{180, 180},
92			{195, 195},
93			{210, 210},
94			{225, 225},
95			{240, 240},
96			{255, 255},
97		};
98	
99	/* EK79007AD2颜色映射表 (基于R36h地址模式配置)*/
100	    u32 lcd_cmap_tbl[2][3][4] = {
101	        {   // SHLR=1 (右移模式)
102	            {LCD_CMAP_G0, LCD_CMAP_B1, LCD_CMAP_G2, LCD_CMAP_B3},
103	            {LCD_CMAP_B0, LCD_CMAP_R1, LCD_CMAP_B2, LCD_CMAP_R3},
104	            {LCD_CMAP_R0, LCD_CMAP_G1, LCD_CMAP_R2, LCD_CMAP_G3},
105	        },
106	        {   // SHLR=0 (左移模式)
107	            {LCD_CMAP_B3, LCD_CMAP_G2, LCD_CMAP_B1, LCD_CMAP_G0},
108	            {LCD_CMAP_R3, LCD_CMAP_B2, LCD_CMAP_R1, LCD_CMAP_B0},
109	            {LCD_CMAP_G3, LCD_CMAP_R2, LCD_CMAP_G1, LCD_CMAP_R0},
110	        },
111	    };
112	    memset(info, 0, sizeof(struct panel_extend_para));
113	
114	    // 生成完整的Gamma校正表
115	    items = sizeof(lcd_gamma_tbl) / 2;
116	    for (i = 0; i < items - 1; i++) {
117	        u32 num = lcd_gamma_tbl[i + 1][0] - lcd_gamma_tbl[i][0];
118	
119	        for (j = 0; j < num; j++) {
120	            u32 value = 0;
121	
122	            value = lcd_gamma_tbl[i][1] +
123	                ((lcd_gamma_tbl[i + 1][1] - lcd_gamma_tbl[i][1]) * j) / num;
124	            info->lcd_gamma_tbl[lcd_gamma_tbl[i][0] + j] =
125	                (value << 16) + (value << 8) + value;
126	        }
127	    }
128	
129	    info->lcd_gamma_tbl[255] = (lcd_gamma_tbl[items - 1][1] << 16) +
130	                               (lcd_gamma_tbl[items - 1][1] << 8) +
131	                               lcd_gamma_tbl[items - 1][1];
132	
133	    // 设置颜色映射表
134	    memcpy(info->lcd_cmap_tbl, lcd_cmap_tbl, sizeof(lcd_cmap_tbl));
135	
136	    syslog(LOG_INFO, "fisker T070S140B: Panel configuration completed successfully\n");
137	}
