163	//上电时序配置
164	static void lcd_power_on(u32 sel)
165	{
166	    panel_reset(sel, GPIO_DATA_LOW);
167	    sunxi_lcd_power_enable(sel, AXP2101_ID_DCDC1);
168	    sunxi_lcd_power_enable(sel, AXP2101_ID_DCDC3);
169	    sunxi_lcd_delay_ms(20);
170	    sunxi_lcd_pin_cfg(sel, 1);
171	    sunxi_lcd_delay_ms(50);
172	    panel_reset(sel, GPIO_DATA_HIGH);
173	    sunxi_lcd_delay_ms(20);
174	    syslog(LOG_INFO, "fisker T070S140B: Step 3 - Release RESET (HIGH - active state)\n");
175	    panel_reset(sel, GPIO_DATA_LOW);
176	    sunxi_lcd_delay_ms(30);
177	
178	    panel_reset(sel, GPIO_DATA_HIGH);
179	    sunxi_lcd_delay_ms(30);
180	    syslog(LOG_INFO, "fisker T070S140B: Step 5 - Enabling AVDD (3.3V - after reset release)\n");
181	    sunxi_lcd_power_enable(sel, AXP2101_ID_DCDC2); // power_id=2 对应配置中的 lcd_power2
182	    sunxi_lcd_delay_ms(20);
183	    syslog(LOG_INFO, "fisker T070S140B: Step 6 - Enabling DSI clock\n");
184	    sunxi_lcd_dsi_clk_enable(sel);
185	    syslog(LOG_INFO, "fisker T070S140B: Power-on sequence completed\n");
186	}
