188	/*下电函数(上电的逆序)*/
189	static void lcd_power_off(u32 sel)
190	{
191	    syslog(LOG_INFO, "fisker T070S140B: Power off sequence started (reverse of power-on), sel=%lu\n", sel);
192	    sunxi_lcd_dsi_clk_disable(sel);
193	    sunxi_lcd_delay_ms(20);
194	    sunxi_lcd_power_disable(sel, AXP2101_ID_DCDC2);
195	    sunxi_lcd_delay_ms(20);
196	    panel_reset(sel, GPIO_DATA_LOW);
197	    sunxi_lcd_delay_ms(20);
198	
199	    sunxi_lcd_pin_cfg(sel,0);
200	    sunxi_lcd_delay_ms(20);
201	
202	    sunxi_lcd_power_disable(sel, AXP2101_ID_DCDC3); // 关闭VDD_IF (1.8V接口电源)
203	    sunxi_lcd_power_disable(sel, AXP2101_ID_DCDC1); // 关闭VDD (1.8V数字电源)
204	}
