    sunxi_lcd_dsi_gen_write_1para(sel, 0xD4, 0x06);
    sunxi_lcd_dsi_gen_write_1para(sel, 0xD5, 0x12);
    sunxi_lcd_dsi_gen_write_1para(sel, 0xD6, 0x0A);
