232	  if(touch_state == TOUCH_VALID){
233	
234	    switch(priv->last_state){
235	
236	      case TOUCH_INVALID:
237	
238	        sample->point[0].flags |= TOUCH_DOWN;
239	        priv->last_state = TOUCH_VALID;
240	        touch_event(priv->lower.priv, sample);
