246	           abs(sample->point[0].y - priv->last_y) > GT911_MOVE_THRESH_PIX)
247	        {
248	          sample->point[0].flags |= TOUCH_MOVE;
249	          priv->last_x = sample->point[0].x;
250	          priv->last_y = sample->point[0].y;
251	        }
252	        else
253	        {
254	          sample->point[0].flags |= TOUCH_DOWN;
255	          priv->last_x = sample->point[0].x;
256	          priv->last_y = sample->point[0].y;
257	        }
258	        touch_event(priv->lower.priv, sample);
259	        break;
260	    }
261	  }
262	  else{
263	
264	    switch(priv->last_state){
265	
266	      case TOUCH_INVALID:
267	
268	       sample->npoints = 0;
269	       memset(&sample->point[0], 0, sizeof(sample->point[0]));
270	       break;
271	
272	      case TOUCH_VALID:
273	
274	       sample->npoints = GT911_MAX_TOUCH_POINTS;
275	       sample->point[0].flags = TOUCH_UP;
276	       sample->point[0].x = priv->last_x;
277	       sample->point[0].y = priv->last_y;
278	       sample->point[0].timestamp = touch_get_time();
279	       priv->last_state = TOUCH_INVALID;
