288	static int gt911_touch_process_data(FAR struct gt911_touch_dev_s *priv,FAR struct touch_sample_s *sample)
289	{
290	  FAR struct gt911_touch_data_s *raw = (FAR struct gt911_touch_data_s *)priv->touch_buf;
291	  if(!TOUCH_POINT_GET_STATUS(raw->status_id) || !TOUCH_POINT_GET_NUM(raw->status_id) || TOUCH_POINT_GET_LARGE(raw->status_id)){
292	
293	    gt911_i2c_write(priv, GT911_REG_COORD_ADDR, 0x00);
294	    return TOUCH_INVALID;
295	  }
296	  sample->npoints = TOUCH_POINT_GET_NUM(raw->status_id);
297	  if (sample->npoints > GT911_MAX_TOUCH_POINTS)
298	    sample->npoints = GT911_MAX_TOUCH_POINTS;
299	
300	  for (int i = 0; i < sample->npoints; i++)
301	  {
302	    /* GT9271 returns coordinates in chip's native resolution
303	     * (touch_max_x x touch_max_y). Scale to LCD pixel resolution
304	     * (1200x1920) since LVGL expects pixel-level values.
305	     * Use max+1 as divisor for clean integer rounding. */
306	    uint16_t raw_x = TOUCH_POINT_GET_X(raw->touch[i]);
307	    uint16_t raw_y = TOUCH_POINT_GET_Y(raw->touch[i]);
308	    uint32_t div_x = (uint32_t)priv->touch_max_x + 1;
309	    uint32_t div_y = (uint32_t)priv->touch_max_y + 1;
310	    sample->point[i].x = (uint16_t)((uint32_t)raw_x * T070S140B_LCD_WIDTH / div_x);
311	    sample->point[i].y = (uint16_t)((uint32_t)raw_y * T070S140B_LCD_HEIGHT / div_y);
312	    sample->point[i].id       = TOUCH_POINT_GET_ID(raw->touch[i]);
313	    sample->point[i].h        = 0;
314	    sample->point[i].w        = 0;
315	    sample->point[i].pressure = TOUCH_POINT_GET_SIZE(raw->touch[i]);
316	    sample->point[i].timestamp = touch_get_time();
317	    memset(&raw->touch[i], 0, sizeof(raw->touch[i]));
318	  }
319	
320	  raw->status_id = 0;
321	  gt911_i2c_write(priv, GT911_REG_COORD_ADDR, 0x00);
322	  return TOUCH_VALID;
323	}
