119	  /* GT911 uses 16-bit register addresses in big-endian format */
120	  addr_buf[0] = (regaddr >> 8) & 0xFF;   /* High byte */
121	  addr_buf[1] = regaddr & 0xFF;          /* Low byte */
122	
123	  /* Set up the address write operation */
124	  msg[0].frequency = priv->frequency;
