131	  msg[1].frequency = priv->frequency;
132	  msg[1].addr      = priv->i2c_addr;
133	  msg[1].flags     = I2C_M_READ;
134	  msg[1].buffer    = buffer;
135	  msg[1].length    = buflen;
136	
137	  ret = I2C_TRANSFER(priv->i2c, msg, 2);
138	  if (ret)
139	    {
